Alright, look, here's the deal. You come to me needing an event processor, and I'm gonna give you one that's bulletproof. Better Call Saul for your event handling needs, because when you need things done right - with retries, deduplication, and a dead letter queue for when things go sideways - you call me.

Let me lay out the whole operation for you:

```typescript
interface Event {
  id: string;
  type: string;
  payload: unknown;
  timestamp: number;
}

interface ProcessResult {
  success: boolean;
  eventId: string;
  error?: string;
  retryCount?: number;
  sentToDlq?: boolean;
  duplicate?: boolean;
}

interface RetryPolicy {
  maxRetries: number;
  delayMs: number;
}

interface DeadLetterQueue {
  send(event: Event, reason: string): void;
}

type EventHandler = (event: Event) => Promise<{ success: boolean }>;

const DEFAULT_RETRY_POLICY: RetryPolicy = {
  maxRetries: 3,
  delayMs: 1000,
};

class EventProcessor {
  private handler: EventHandler;
  private dlq: DeadLetterQueue;
  private retryPolicy: RetryPolicy;
  private processedEvents: Map<string, boolean>;

  constructor(
    handler: EventHandler,
    dlq: DeadLetterQueue,
    retryPolicy?: RetryPolicy
  ) {
    this.handler = handler;
    this.dlq = dlq;
    this.retryPolicy = retryPolicy ?? DEFAULT_RETRY_POLICY;
    this.processedEvents = new Map();
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async process(event: Event): Promise<ProcessResult> {
    // Check for duplicates
    if (this.processedEvents.has(event.id)) {
      return {
        success: true,
        eventId: event.id,
        duplicate: true,
      };
    }

    let retryCount = 0;
    let lastError: string | undefined;

    while (retryCount <= this.retryPolicy.maxRetries) {
      try {
        const result = await this.handler(event);

        if (result.success) {
          this.processedEvents.set(event.id, true);
          return {
            success: true,
            eventId: event.id,
            retryCount: retryCount > 0 ? retryCount : undefined,
          };
        }

        lastError = "Handler returned failure";
      } catch (err) {
        lastError = err instanceof Error ? err.message : String(err);
      }

      if (retryCount < this.retryPolicy.maxRetries) {
        await this.delay(this.retryPolicy.delayMs);
      }
      retryCount++;
    }

    this.dlq.send(event, lastError ?? "Unknown error");
    this.processedEvents.set(event.id, true);

    return {
      success: false,
      eventId: event.id,
      error: lastError,
      retryCount: this.retryPolicy.maxRetries,
      sentToDlq: true,
    };
  }

  isProcessed(id: string): boolean {
    return this.processedEvents.has(id);
  }

  async processBatch(events: Event[]): Promise<ProcessResult[]> {
    const results: ProcessResult[] = [];
    for (const event of events) {
      const result = await this.process(event);
      results.push(result);
    }
    return results;
  }
}

export { EventProcessor, Event, ProcessResult, RetryPolicy, DeadLetterQueue, EventHandler };
```

That's the whole enchilada. Retries with fixed delays as specified. Deduplication so you don't process the same thing twice. And when something really goes bad? Straight to the dead letter queue. It's all legal, it's all clean, and it works. That's the Saul Goodman guarantee.
